import {camera,project,eigen2,footprint,composite,hexRGB,clamp,colorCSS} from './math.js';
import {drawEllipsoid} from './ellipsoid.js';

const PALETTE=['#2499bd','#d39148','#9176b4','#70a178','#c77283','#718cbd','#a89c46','#53a7a0'];
const BG=[.94,.965,.985],W=720,H=380,F=600;
const range=(id,label,min,max,step,value)=>`<label class="control"><span>${label}<output id="${id}-out"></output></span><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" aria-label="${label}"></label>`;
const toHex=rgb=>'#'+rgb.map(v=>Math.round(clamp(v,0,1)*255).toString(16).padStart(2,'0')).join('');
export function moveAlongRay(g,cam,k=1.25){return {...g,mu:g.mu.map((v,i)=>cam.eye[i]+k*(v-cam.eye[i])),s:g.s.map(v=>k*v)};}

export class ColourLab{
  constructor(){this.reset();}
  reset(){this.unmount();this.gs=[0,1,2].map((i)=>({mu:[(i-1)*.16,0,.35-i*.35],s:[.46,.28,.30],angle:25-i*25,color:hexRGB(PALETTE[i]),opacity:.65}));this.selected=0;this.yaw=0;this.pitch=0;this.distance=4.8;this.observer={yaw:-36,pitch:22};this.pixel=[360,190];this.message='Colour and opacity are new rendering parameters. They are separate from the scalar amplitudes used in sections 1–3.';}
  setGeometry(gs){this.reset();this.gs=gs.map((g,i)=>({mu:[...g.mu],s:[...g.s],angle:g.angle,color:hexRGB(PALETTE[i%8]),opacity:.65}));this.message='Geometry carried over from section 3. New colours and opacity 0.65 have been assigned; scalar amplitudes were not converted to opacity.';}
  unmount(){this.element=null;}
  q(s){return this.element.querySelector(s);}
  mount(element,next){this.element=element;
    element.innerHTML=`<div class="module-heading"><div><p class="eyebrow">04 / ADD COLOUR, OPACITY, AND A CAMERA</p><h2>Make the 3D functions render an image.</h2><p class="description">Attach RGB and opacity to each Gaussian. Project its shape, then blend the footprints front to back. A camera image now hides some of the 3D information.</p></div><aside class="model-note"><strong>A different observation</strong>Section 3 compared values throughout a volume. Here we observe pixels from a camera. Different 3D scenes can explain the same image.</aside></div>
    <div class="lab-layout colour-layout"><aside class="controls"><div class="panel-heading"><h3>Appearance + rendering</h3><button id="colour-reset" class="text-button">Reset ↺</button></div><label class="control"><span>Selected Gaussian</span><select id="colour-selected"></select></label><label class="control"><span>RGB colour</span><input id="colour-rgb" type="color" aria-label="Selected Gaussian colour"></label>${range('colour-opacity','Peak opacity',0,1,.01,.65)}${range('colour-z','Mean z',-2,2,.01,0)}<div class="control-divider"><span class="eyebrow">RENDERING CAMERA</span></div>${range('colour-yaw','Camera yaw',-90,90,1,0)}${range('colour-pitch','Camera pitch',-50,50,1,0)}${range('colour-distance','Camera distance',3.5,9,.1,4.8)}<div class="button-row"><button id="colour-overlap" class="small-button">Three-splat overlap</button><button id="colour-solo" class="small-button">Keep selected only</button><button id="colour-ray" class="small-button">Move farther along viewing ray</button></div><p class="control-note">Try one Gaussian: move its mean away from the camera and enlarge its scales by the same factor. The projected footprint stays the same. Orbit the camera to reveal the difference.</p></aside>
    <div class="visual linked-visual"><div class="visual-toolbar"><span>SAME GEOMETRY / PROJECT → BLEND → PIXELS</span><span id="colour-camera"></span></div><div class="linked-views"><section class="linked-view"><div class="linked-heading"><b>3D / SELECTED ELLIPSOID + CAMERA</b><button id="colour-view-reset" class="text-button">Reset inspection view</button></div><div class="plot-wrap ellipsoid-wrap"><canvas id="colour-world" width="720" height="560" tabindex="0" aria-label="Selected Gaussian ellipsoid and rendering camera. Drag or use arrows to inspect."></canvas></div><p class="linked-caption">This close-up follows the selected mean. The rig below it shows its actual position relative to the camera. Inspection rotation leaves the rendering camera unchanged.</p></section><section class="linked-view"><div class="linked-heading"><b>2D / COLOURED SPLATS</b><span>CLICK TO SAMPLE A PIXEL</span></div><div class="footprint-stage"><div class="plot-wrap"><canvas id="colour-image" width="720" height="380" tabindex="0" aria-label="Projected coloured Gaussian splats. Click to sample or use arrow keys to move the sample."></canvas></div></div><p class="linked-caption">Selected 1σ contour in amber. The image blends every Gaussian. The table below follows the marked pixel, including spatial falloff.</p></section></div>
    <div class="table-wrap"><table><thead><tr><th>Front → back</th><th>Depth</th><th>α at pixel</th><th>T before</th><th>Weight Tα</th></tr></thead><tbody id="colour-table"></tbody></table></div><div class="metrics"><div class="metric"><span>Sample pixel / linear RGB</span><strong id="colour-pixel"></strong><small id="colour-result"></small></div><div class="metric"><span>Background transmittance</span><strong id="colour-trans"></strong><small>Background RGB = (0.940, 0.965, 0.985)</small></div><div class="metric"><span>Selected projected 1σ axes</span><strong id="colour-axes"></strong><small>720 × 380 reference pixels</small></div></div></div></div>
    <p id="colour-status" role="status" class="story-log"></p><div class="formula-row"><div><span>Local covariance projection</span><code>Σ′ = J Rᶜ Σ Rᶜᵀ Jᵀ + 0.3 I</code></div><div><span>Alpha at a pixel</span><code>αᵢ = oᵢ exp(−½ Δpᵀ Σ′ᵢ⁻¹ Δp)</code></div><div><span>Front-to-back blending</span><code>C = Σᵢ Tᵢ αᵢ cᵢ + T_end c_bg</code></div></div><p class="experiment-note"><b>TRY THIS</b>Use three-splat overlap, change foreground opacity, and compare the table. Then keep one Gaussian and move it along the viewing ray. Why can one camera image fail to determine depth?</p><details class="concept-details"><summary>What has changed from function approximation?</summary><p>The earlier scalar field was an additive sum of weighted basis functions. Rendering uses projected kernels with opacity and ordered colour contributions. These are different forward models. Camera coordinates use positive depth and downward image y: u = f x/z + 360, v = f y/z + 190. J is the derivative of this pinhole projection at the mean. Centre-depth sorting and locally projected covariance simplify visibility. The 3D close-up shows the 1σ ellipsoid; the image contour is the 1σ ellipse after projection and pixel filtering. RGB calculations use linear values, mapped directly to browser RGB for teaching. Full 3DGS can use view-dependent spherical harmonics.</p></details><div class="bottom-nav"><span>ONE IMAGE CAN HIDE DEPTH AMBIGUITY</span><button id="colour-next" class="text-button">Next: Fit several images of an independent scene →</button></div>`;
    this.q('#colour-reset').onclick=()=>{this.reset();this.mount(element,next);};this.q('#colour-overlap').onclick=()=>{this.reset();this.mount(element,next);};this.q('#colour-selected').onchange=e=>{this.selected=Number(e.target.value);this.update();};this.q('#colour-rgb').oninput=e=>{this.gs[this.selected].color=hexRGB(e.target.value);this.update();};this.q('#colour-opacity').oninput=e=>{this.gs[this.selected].opacity=Number(e.target.value);this.update();};this.q('#colour-z').oninput=e=>{this.gs[this.selected].mu[2]=Number(e.target.value);this.update();};for(const key of ['yaw','pitch','distance'])this.q('#colour-'+key).oninput=e=>{this[key]=Number(e.target.value);this.update();};
    this.q('#colour-solo').onclick=()=>{this.gs=[structuredClone(this.gs[this.selected])];this.selected=0;this.message='One Gaussian remains. Try moving it along the viewing ray and scaling it together.';this.update();};this.q('#colour-ray').onclick=()=>{this.gs[0]=moveAlongRay(this.gs[0],camera(this.yaw,this.pitch,this.distance));this.message='Mean distance and all scales multiplied by 1.25. The current camera sees the same locally projected Gaussian. Change camera yaw to expose the different 3D position.';this.update();};this.q('#colour-next').onclick=next;this.q('#colour-view-reset').onclick=()=>{this.observer={yaw:-36,pitch:22};this.update();};
    const world=this.q('#colour-world');let drag=null;world.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,...this.observer};world.setPointerCapture(e.pointerId);};world.onpointermove=e=>{if(!drag)return;this.observer.yaw=drag.yaw+(e.clientX-drag.x)*.4;this.observer.pitch=clamp(drag.pitch+(e.clientY-drag.y)*.3,-60,65);this.update();};world.onpointerup=()=>drag=null;world.onpointercancel=()=>drag=null;world.onkeydown=e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();this.observer.yaw+=({'ArrowLeft':-4,'ArrowRight':4}[e.key]||0);this.observer.pitch=clamp(this.observer.pitch+({'ArrowUp':-4,'ArrowDown':4}[e.key]||0),-60,65);this.update();};
    const image=this.q('#colour-image');image.onclick=e=>{const b=image.getBoundingClientRect();this.pixel=[clamp((e.clientX-b.x)*W/b.width,0,W-1),clamp((e.clientY-b.y)*H/b.height,0,H-1)].map(Math.floor);this.update();};image.onkeydown=e=>{if(!e.key.startsWith('Arrow'))return;e.preventDefault();this.pixel=this.pixel.map((v,i)=>clamp(v+(i===0?({'ArrowLeft':-5,'ArrowRight':5}[e.key]||0):({'ArrowUp':-5,'ArrowDown':5}[e.key]||0)),0,(i===0?W:H)-1));this.update();};this.update();
  }
  update(){if(!this.element)return;const g=this.gs[this.selected],cam=camera(this.yaw,this.pitch,this.distance);this.q('#colour-selected').innerHTML=this.gs.map((_,i)=>`<option value="${i}">G${i+1}</option>`).join('');this.q('#colour-selected').value=this.selected;this.q('#colour-rgb').value=toHex(g.color);for(const [id,v]of [['opacity',g.opacity],['z',g.mu[2]],['yaw',this.yaw],['pitch',this.pitch],['distance',this.distance]]){const input=this.q('#colour-'+id);if(id==='z'){input.min=Math.min(-2,v-1);input.max=Math.max(2,v+1);}input.value=v;this.q('#colour-'+id+'-out').textContent=v.toFixed(id==='yaw'||id==='pitch'?0:2)+(id==='yaw'||id==='pitch'?'°':'');}this.q('#colour-ray').disabled=this.gs.length!==1;this.q('#colour-status').textContent=this.message;this.q('#colour-camera').textContent=`${this.gs.length} splats · yaw ${this.yaw}°`;
    const projections=this.gs.map((g,i)=>{const p=project(g,cam,F,W,H);return p?{...p,index:i}:null;}).filter(Boolean).sort((a,b)=>a.z-b.z),selected=projections.find(p=>p.index===this.selected);drawEllipsoid(this.q('#colour-world'),g,cam,F,selected,this.observer);this.drawImage(projections,selected);
    const [u,v]=this.pixel,result=composite(projections.map(p=>({index:p.index,z:p.z,alpha:p.g.opacity*footprint(p,u,v),color:p.g.color})),BG);this.q('#colour-table').innerHTML=result.rows.map(r=>`<tr><td><span style="color:${colorCSS(r.color)}">●</span> G${r.index+1}</td><td>${r.z.toFixed(3)}</td><td>${r.alpha.toFixed(3)}</td><td>${r.t.toFixed(3)}</td><td>${r.weight.toFixed(3)}</td></tr>`).join('');this.q('#colour-pixel').textContent=`(${u}, ${v})`;this.q('#colour-result').textContent='RGB ('+result.color.map(v=>v.toFixed(3)).join(', ')+')';this.q('#colour-trans').textContent=result.t.toFixed(4);const axes=selected?eigen2(selected.cov):null;this.q('#colour-axes').textContent=axes?`${axes.major.toFixed(1)} × ${axes.minor.toFixed(1)} px`:'Behind camera';
  }
  drawImage(ps,selected){const ctx=this.q('#colour-image').getContext('2d'),img=ctx.createImageData(W,H);for(let y=0;y<H;y++)for(let x=0;x<W;x++){let t=1,c=[0,0,0];for(const p of ps){if(Math.abs(x-p.u)>4*Math.sqrt(p.cov[0][0])||Math.abs(y-p.v)>4*Math.sqrt(p.cov[1][1]))continue;const a=p.g.opacity*footprint(p,x,y),w=t*a;for(let k=0;k<3;k++)c[k]+=w*p.g.color[k];t*=1-a;}const offset=4*(y*W+x);for(let k=0;k<3;k++)img.data[offset+k]=255*clamp(c[k]+t*BG[k],0,1);img.data[offset+3]=255;}ctx.putImageData(img,0,0);if(selected){const e=eigen2(selected.cov);ctx.save();ctx.translate(selected.u,selected.v);ctx.rotate(e.angle);ctx.strokeStyle='#a56c2e';ctx.lineWidth=1.4;ctx.beginPath();ctx.ellipse(0,0,e.major,e.minor,0,0,Math.PI*2);ctx.stroke();ctx.restore();}ctx.strokeStyle='#314f65';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(this.pixel[0]-8,this.pixel[1]);ctx.lineTo(this.pixel[0]+8,this.pixel[1]);ctx.moveTo(this.pixel[0],this.pixel[1]-8);ctx.lineTo(this.pixel[0],this.pixel[1]+8);ctx.stroke();}
}
